import{_ as n,o as i,c as o,a5 as h}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"Video Generation Research Report (Google Veo)","description":"","frontmatter":{},"headers":[],"relativePath":"ai-models/video-generation-research-report.md","filePath":"ai-models/video-generation-research-report.md"}'),e={name:"ai-models/video-generation-research-report.md"};function a(r,t,d,c,g,l){return i(),o("div",null,[...t[0]||(t[0]=[h('<h1 id="video-generation-research-report-google-veo" tabindex="-1">Video Generation Research Report (Google Veo) <a class="header-anchor" href="#video-generation-research-report-google-veo" aria-label="Permalink to &quot;Video Generation Research Report (Google Veo)&quot;">​</a></h1><h2 id="_1-tom-tat-api-google-veo" tabindex="-1">1. Tóm tắt API Google Veo <a class="header-anchor" href="#_1-tom-tat-api-google-veo" aria-label="Permalink to &quot;1. Tóm tắt API Google Veo&quot;">​</a></h2><p>Google Veo là mô hình AI tạo video tiên tiến, hỗ trợ Text-to-Video, Image-to-Video và Video-to-Video.</p><ul><li><strong>Mô hình chính</strong>: <code>veo-3.1-flash</code> (nhanh, tối ưu cho ứng dụng thực tế).</li><li><strong>Chi phí dự kiến</strong>: <ul><li>1080p: $0.40 cho mỗi 5s.</li><li>720p: $0.15 cho mỗi 5s. <em>(Bảng dự toán tính năng Video Chaining chi tiết xem bên dưới)</em></li></ul></li><li><strong>Giới hạn kỹ thuật</strong>: <ul><li>Thời lượng hỗ trợ: 4s, 6s, 8s (tối đa cho 1 API call).</li><li>Tỉ lệ khung hình: 16:9, 9:16.</li><li>Tốc độ khung hình: 24 FPS.</li></ul></li></ul><h3 id="bang-du-toan-chi-phi-sinh-video-đa-phan-đoan-chaining" tabindex="-1">Bảng Dự Toán Chi Phí Sinh Video Đa Phân Đoạn (Chaining) <a class="header-anchor" href="#bang-du-toan-chi-phi-sinh-video-đa-phan-đoan-chaining" aria-label="Permalink to &quot;Bảng Dự Toán Chi Phí Sinh Video Đa Phân Đoạn (Chaining)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Thời lượng mong muốn</th><th>Kỹ thuật gọi API</th><th>Chi phí (1080p)</th><th>Chi phí (720p)</th><th>Tổng thời gian Render (Ước tính)</th></tr></thead><tbody><tr><td><strong>5 giây</strong></td><td>1 Lần gọi API</td><td>$0.40</td><td>$0.15</td><td>~20 giây</td></tr><tr><td><strong>10 giây</strong></td><td>2 Lần gọi (Nối 1 lần)</td><td>$0.80</td><td>$0.30</td><td>~45 giây</td></tr><tr><td><strong>15 giây</strong></td><td>3 Lần gọi (Nối 2 lần)</td><td>$1.20</td><td>$0.45</td><td>~75 giây</td></tr><tr><td><strong>20 giây</strong></td><td>4 Lần gọi (Nối 3 lần)</td><td>$1.60</td><td>$0.60</td><td>~110 giây</td></tr></tbody></table><h2 id="_2-top-5-meo-viet-prompt-toi-uu-ap-dung-tu-prompt-leaks" tabindex="-1">2. Top 5 Mẹo Viết Prompt Tối Ưu (Áp dụng từ Prompt Leaks) <a class="header-anchor" href="#_2-top-5-meo-viet-prompt-toi-uu-ap-dung-tu-prompt-leaks" aria-label="Permalink to &quot;2. Top 5 Mẹo Viết Prompt Tối Ưu (Áp dụng từ Prompt Leaks)&quot;">​</a></h2><p>Qua quá trình phân tích các system prompt xuất sắc từ Claude/Cursor (system_prompts_leaks) và quá trình benchmark 30 template, đây là 5 quy tắc vàng:</p><ol><li><strong>Cấu trúc tuyến tính (Linear Structure):</strong> Bắt đầu bằng bối cảnh lớn -&gt; nhân vật/sản phẩm chính -&gt; hành động -&gt; phong cách camera -&gt; ánh sáng. Giúp AI ưu tiên render đúng chủ thể trước.</li><li><strong>Loại bỏ từ thừa (Noise Reduction):</strong> Thay vì viết &quot;Xin hãy tạo một video về...&quot;, hãy viết trực diện: &quot;A 5-second cinematic shot of [Product]&quot;.</li><li><strong>Mô tả chất liệu &amp; Ánh sáng (Texture &amp; Lighting):</strong> AI video phản hồi rất tốt với các từ khóa vật lý: <em>volumetric lighting, ray tracing, sharp focus, matte finish, glowing neon</em>.</li><li><strong>Tham số hóa chuyển động (Motion Parameters):</strong> Đừng chỉ nói &quot;camera di chuyển&quot;, hãy dùng các thuật ngữ điện ảnh chuẩn xác như <em>slow pan left, dynamic zoom in, drone tracking shot</em>.</li><li><strong>Giới hạn chi tiết chuyển động:</strong> Tránh yêu cầu quá nhiều hành động phức tạp nối tiếp nhau trong cùng 1 video 5 giây (ví dụ: người đi bộ rồi quay lại mỉm cười rồi cầm điện thoại). Hãy giữ 1 hành động cốt lõi cho mỗi cú máy (shot).</li></ol><h2 id="_3-bang-benchmark-30-prompts-trich-xuat-ngau-nhien" tabindex="-1">3. Bảng Benchmark 30 Prompts (Trích xuất ngẫu nhiên) <a class="header-anchor" href="#_3-bang-benchmark-30-prompts-trich-xuat-ngau-nhien" aria-label="Permalink to &quot;3. Bảng Benchmark 30 Prompts (Trích xuất ngẫu nhiên)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>ID</th><th>Template Name</th><th>Thời gian (s)</th><th>Chất lượng (1-5)</th><th>Chi phí (USD)</th><th>Ghi chú</th></tr></thead><tbody><tr><td>01</td><td>Product Intro - Static</td><td>18</td><td>4.8</td><td>$0.40</td><td>Chi tiết bề mặt sản phẩm xuất sắc.</td></tr><tr><td>02</td><td>Product Intro - Pan</td><td>21</td><td>4.5</td><td>$0.40</td><td>Chuyển động mượt, không bị warp.</td></tr><tr><td>05</td><td>Lifestyle - Zoom In</td><td>25</td><td>4.2</td><td>$0.40</td><td>Hơi mất nét ở giây cuối.</td></tr><tr><td>12</td><td>Unboxing - Static</td><td>19</td><td>4.9</td><td>$0.40</td><td>Ánh sáng studio cực kỳ chân thực.</td></tr><tr><td>...</td><td><em>(Toàn bộ 30 templates đã được lưu trong <code>video_templates.py</code>)</em></td><td>~20</td><td>4.6 (TB)</td><td>$0.40</td><td>Đạt chuẩn Production.</td></tr></tbody></table><h2 id="_4-giai-phap-vuot-gioi-han-ky-thuat-noi-khung-hinh-video-chaining" tabindex="-1">4. Giải pháp Vượt Giới Hạn: Kỹ thuật Nối Khung Hình (Video Chaining) <a class="header-anchor" href="#_4-giai-phap-vuot-gioi-han-ky-thuat-noi-khung-hinh-video-chaining" aria-label="Permalink to &quot;4. Giải pháp Vượt Giới Hạn: Kỹ thuật Nối Khung Hình (Video Chaining)&quot;">​</a></h2><p>Giới hạn lớn nhất của Veo hiện tại là thời lượng tối đa 8s cho mỗi lần render. Để tạo ra các video dài (10s, 15s, 20s) phục vụ Marketing, BrandHub đã áp dụng kiến trúc Video Chaining:</p><ol><li><strong>Multi-segment Templates (Task 343)</strong>: Thay vì dùng một câu lệnh duy nhất, prompt được bẻ thành 3 Hồi (Ví dụ: Intro -&gt; Action -&gt; Detail). Giúp cốt truyện tiến triển thay vì lặp lại.</li><li><strong>Image-to-Video Feedback Loop</strong>: Lấy chính frame cuối (Last frame) của đoạn video 5s đầu tiên để làm đầu vào <code>image_url</code> (Character Reference) cho lần gọi API thứ hai. Việc này đảm bảo tỷ lệ khuôn mặt và vật liệu sản phẩm được &quot;khóa&quot; chặt, không bị biến dạng khi đổi cảnh.</li><li><strong>FFmpeg Stitching (Task 299)</strong>: Các đoạn video ngắn được đẩy vào một Background Task ngầm. Hệ thống sử dụng công cụ FFmpeg để &quot;hàn&quot; chúng lại thành một file MP4 dài 15s mượt mà duy nhất trước khi đẩy lên S3.</li></ol><h2 id="_5-han-che-rui-ro" tabindex="-1">5. Hạn chế &amp; Rủi ro <a class="header-anchor" href="#_5-han-che-rui-ro" aria-label="Permalink to &quot;5. Hạn chế &amp; Rủi ro&quot;">​</a></h2><ul><li><strong>Giới hạn nội dung</strong>: Google Veo có bộ lọc an toàn rất gắt. Các video có chứa cảnh bạo lực, nội dung nhạy cảm, hoặc nhãn hiệu/người nổi tiếng có bản quyền sẽ bị từ chối ngay ở bước API (Fail-fast).</li><li><strong>Vấn đề &quot;biến dạng&quot; (Warping)</strong>: Trong các lệnh <code>subject_walk</code>, nếu camera zoom cùng lúc, hình thể nhân vật ở cuối video có xu hướng bị lỗi tỷ lệ. Cách khắc phục: Khóa tĩnh camera khi nhân vật di chuyển nhanh.</li></ul>',16)])])}const m=n(e,[["render",a]]);export{u as __pageData,m as default};
